style.css:
@-moz-document domain("vk.com") {
/* === Background Image === */
body {
    background: url(https://1drv.ms/i/c/f82eb7c52ea3a33b/IQAhjv0K5wHxSYR8qJTv8CVGAdzCYg1_7_DIB_7Aw38Y490?e=jdB5lw) no-repeat center center fixed !important;
    background-size: cover !important;
}

/* Optional warm overlay for better readability */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(90, 62, 43, 0.35); /* warm brown overlay */
    z-index: -1;
}

/* === Header === */
#page_header {
    background: rgba(107, 79, 58, 0.9) !important;
    backdrop-filter: blur(6px);
}

/* === Sidebar === */
#side_bar {
    background: rgba(230, 210, 184, 0.75) !important;
    backdrop-filter: blur(6px);
    border-radius: 12px;
}

/* === Translucent Content Blocks === */
.page_block {
    background: rgba(255, 250, 243, 0.70) !important;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-radius: 14px !important;
    border: 1px solid rgba(140, 94, 60, 0.25) !important;
    box-shadow: 0 8px 25px rgba(60, 40, 30, 0.25) !important;
}

/* === Buttons === */
button,
.flat_button,
.ui_button {
    background: #8b5e3c !important;
    color: #fff !important;
    border-radius: 6px !important;
    border: none !important;
}

button:hover,
.flat_button:hover,
.ui_button:hover {
    background: #6b4f3a !important;
}

/* === Links === */
a {
    color: #f2d2a9 !important;
}

a:hover {
    color: #ffffff !important;
}
}
